   742  otError Leader::RegisterNetworkData(uint16_t aRloc16, uint8_t *aTlvs, uint8_t aTlvsLength)
   743  {
   744      otError error         = OT_ERROR_NONE;
   745      bool    rlocIn        = false;
   746      bool    rlocStable    = false;
   747      bool    stableUpdated = false;
   748      bool    unused;
   749      uint8_t oldTlvs[NetworkData::kMaxSize];
   750      uint8_t oldTlvsLength = NetworkData::kMaxSize;
   751
   752      // Verify that `aTlvs` only contains entries matching `aRloc16`.
   753      SuccessOrExit(error = RlocLookup(aRloc16, rlocIn, rlocStable, aTlvs, aTlvsLength, kMatchModeRloc16,
   754                                       /* aAllowOtherEntries */ false));
   755
   756      RlocLookup(aRloc16, rlocIn, unused, mTlvs, mLength, kMatchModeRloc16);
   757
   758      if (rlocIn)
   759      {
   760          if (IsStableUpdated(aTlvs, aTlvsLength, mTlvs, mLength) || IsStableUpdated(mTlvs, mLength, aTlvs, aTlvsLength))
   761          {
   762              stableUpdated = true;
   763          }
   764
   765          // Store old Service IDs for given rloc16, so updates to server will reuse the same Service ID
   766          SuccessOrExit(error = GetNetworkData(false, oldTlvs, oldTlvsLength));
   767
   768          RemoveRloc(aRloc16, kMatchModeRloc16);
   769          SuccessOrExit(error = AddNetworkData(aTlvs, aTlvsLength, oldTlvs, oldTlvsLength));
   770
   771          mVersion++;
   772
   773          if (stableUpdated)
   774          {
   775              mStableVersion++;
   776          }
   777      }
   778      else
   779      {
   780          // No old data to be preserved, lets avoid memcpy() & FindService calls.
   781          SuccessOrExit(error = AddNetworkData(aTlvs, aTlvsLength, oldTlvs, 0));
   782
   783          mVersion++;
   784
   785          if (rlocStable)
   786          {
   787              mStableVersion++;
   788          }
   789      }
