   349  otError Local::SendServerDataNotification(void)
   350  {
   351      otError  error = OT_ERROR_NONE;
   352      uint16_t rloc  = Get<Mle::MleRouter>().GetRloc16();
   353
   354  #if OPENTHREAD_FTD
   355
   356      // Don't send this Server Data Notification if the device is going to upgrade to Router
   357      if (Get<Mle::MleRouter>().IsFullThreadDevice() && Get<Mle::MleRouter>().IsRouterRoleEnabled() &&
   358          (Get<Mle::MleRouter>().GetRole() < OT_DEVICE_ROLE_ROUTER) &&
   359          (Get<RouterTable>().GetActiveRouterCount() < Get<Mle::MleRouter>().GetRouterUpgradeThreshold()))
   360      {
   361          ExitNow(error = OT_ERROR_INVALID_STATE);
   362      }
   363
   364  #endif
   365
   366      UpdateRloc();
   367
   368  #if OPENTHREAD_ENABLE_SERVICE
   369      VerifyOrExit(!IsOnMeshPrefixConsistent() || !IsExternalRouteConsistent() || !IsServiceConsistent(),
   370                   ClearResubmitDelayTimer());
   371  #else
   372      VerifyOrExit(!IsOnMeshPrefixConsistent() || !IsExternalRouteConsistent(), ClearResubmitDelayTimer());
   373  #endif
   374
   375      if (mOldRloc == rloc)
   376      {
   377          mOldRloc = Mac::kShortAddrInvalid;
   378      }
   379
   380      SuccessOrExit(error = NetworkData::SendServerDataNotification(mOldRloc));
   381      mOldRloc = rloc;
   382
   383  exit:
   384      return error;
   385  }
